// Package fixture synthesizes all input material medialab processes. No
// external media files are referenced: MXF, MP4 and RTP samples are
// generated from an integer seed so every run is byte-for-byte
// reproducible, including injected damage.
package fixture

// Rand is a small deterministic xorshift64* generator. math/rand is
// intentionally avoided so generated bytes do not change across Go
// versions or runtime seeding.
type Rand struct {
	state uint64
}

// NewRand derives the generator state from an integer seed using
// splitmix64, which spreads close seed values far apart.
func NewRand(seed int64) *Rand {
	r := &Rand{}
	x := uint64(seed)
	x += 0x9E3779B97F4A7C15
	x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9
	x = (x ^ (x >> 27)) * 0x94D049BB133111EB
	r.state = x ^ (x >> 31)
	if r.state == 0 {
		r.state = 0xDEADBEEF
	}
	return r
}

// Uint64 returns the next pseudo-random uint64.
func (r *Rand) Uint64() uint64 {
	x := r.state
	x ^= x >> 12
	x ^= x << 25
	x ^= x >> 27
	r.state = x
	return x * 0x2545F4914F6CDD1D
}

// Intn returns a value in [0, n). It panics for n <= 0, mirroring the
// math/rand convention.
func (r *Rand) Intn(n int) int {
	if n <= 0 {
		panic("fixture: Intn bound must be positive")
	}
	return int(r.Uint64() % uint64(n))
}

// Uint32 returns the next pseudo-random uint32.
func (r *Rand) Uint32() uint32 {
	return uint32(r.Uint64() >> 32)
}

// Fill writes a deterministic pseudo-random byte pattern into b.
func (r *Rand) Fill(b []byte) {
	for len(b) >= 8 {
		v := r.Uint64()
		for i := 0; i < 8; i++ {
			b[i] = byte(v >> (8 * i))
		}
		b = b[8:]
	}
	if len(b) > 0 {
		v := r.Uint64()
		for i := range b {
			b[i] = byte(v >> (8 * i))
		}
	}
}

// Perm returns a permutation of [0,n) using Fisher-Yates.
func (r *Rand) Perm(n int) []int {
	p := make([]int, n)
	for i := range p {
		p[i] = i
	}
	for i := n - 1; i > 0; i-- {
		j := r.Intn(i + 1)
		p[i], p[j] = p[j], p[i]
	}
	return p
}
